for dirpath, _, files in os.walk(ROOT):
    csvs = [f for f in files if f.lower().endswith(".csv")]
    if not csvs:
        continue

    model = MODEL_NAME

    for csv in csvs:
        csv_path = os.path.join(dirpath, csv)
        try:
            df = pd.read_csv(
                csv_path,
                header=None,
                dtype=str,
                keep_default_na=False
            )
        except FileNotFoundError:
            print(f"WARNING: File not found: {csv_path}")
            continue
        except pd.errors.EmptyDataError:
            print(f"WARNING: Empty CSV file: {csv_path}")
            continue
        except pd.errors.ParserError as e:
            print(f"WARNING: Failed to parse CSV {csv_path}: {e}")
            continue
        except Exception as e:
            print(f"WARNING: Unexpected error reading {csv_path}: {e}")
            continue

        # Verify CSV has at least 6 columns
        if df.shape[1] < 6:
            print(f"WARNING: CSV {csv_path} has fewer than 6 columns (found {df.shape[1]}). Skipping.")
            continue

        processed_files += 1

        id = df.iloc[:, 0].astype(str).str.strip()
        gt = df.iloc[:, 3].astype(str).str.strip()
        pred_raw = df.iloc[:, 4].astype(str)

        # Extract inference times from column 5 (individual row times)
        try:
            inference_times = pd.to_numeric(df.iloc[:, 5], errors='coerce').fillna(0.0)
        except Exception:
            inference_times = pd.Series([0.0] * len(df))

        pred_clean = (
            pred_raw
            .str.extract(oracle_re, expand=False)
            .fillna(pred_raw)
            .str.strip()
        )

        for idx, (id, g, p, inf_time) in enumerate(zip(id, gt, pred_clean, inference_times)):
            #if ("-".join(id.split("-")[:-1]),g) in ids_correct:
            if True:
                strict = (g.replace(" ","") == p.replace(" ","")) or (g.replace(" ","") == (p.replace(" ","") + ";"))
                flex = strict or (g.replace(" ","") in p.replace(" ","")) or (p.replace(" ","") in g.replace(" ",""))

                # Determine Claude equivalence
                if (not flex) and (not p == "" or ("assert" not in p.lower())):
                    claude_batch_requests.append(create_claude_request(f"llm-r-{request_counter}", g,p))
                    request_counter += 1
                    #claude_equiv = compare_java_equivalence(g, p)

                # Print progress every 100 comparisons
                # if (stats[model]["total"] + 1) % 100 == 0:
                #     print(f"Processing {model}: {stats[model]['total'] + 1} samples, "
                #           f"last Claude equivalence: {claude_equiv}")

                stats[model]["strict"] += int(strict)
                stats[model]["flex"] += int(flex)
                #stats[model]["claude_equivalent"] += int(claude_equiv)
                stats[model]["inference_time"] += float(inf_time)

                # Prediction is empty or doesn't contain 'assert'
                if p == "" or ("assert" not in p.lower()):
                    stats[model]["empty"] += 1

                stats[model]["total"] += 1

print(f"\n✓ Processed {processed_files} CSV file(s)")

# ------------------------- console output -------------------------
print("\n" + "=" * 80)
print("METRICS:")
print(" strict = (groundtruth == prediction) or (groundtruth == prediction + ';')")
print(" flex = strict or (groundtruth in prediction) or (prediction in groundtruth)")
print(" claude_equiv = Claude Sonnet determines semantic equivalence")
print("=" * 80)
print("\nPROMPTS:")
print(" Prompt 1: Test prefix + invoked methods")
print(" Prompt 2: Test prefix + invoked methods + focal class")
print(" Prompt 3: Test prefix + invoked methods + test class")
print(" Prompt 4: Test prefix + invoked methods + test class + focal class")
print("\n" + "=" * 80)
print("RESULTS:")
print("=" * 80 + "\n")

for m, s in sorted(stats.items()):
    t = s["total"]
    if t == 0:
        continue

    strict_pct = 100 * s["strict"] / t
    flex_pct = 100 * s["flex"] / t
    empty_pct = 100 * s["empty"] / t
    inference_time_avg = s["inference_time"] / t
    claude_equiv_pct = 100 * s["claude_equivalent"] / t

    print(f"{m}")
    print(f" Strict: {s['strict']:4d} / {t} ({strict_pct:5.1f}%)")
    print(f" Flexible: {s['flex']:4d} / {t} ({flex_pct:5.1f}%)")
    print(f" Empty: {s['empty']:4d} / {t} ({empty_pct:5.1f}%)")
    print(f" Claude Equiv: {s['claude_equivalent']:4d} / {t} ({claude_equiv_pct:5.1f}%)")
    print(f" Inf. Time: {inference_time_avg:.2f} sec")
    print()

# ------------------------ JSON serialisation ----------------------
json_data = {
    model: {
        "total": s["total"],
        "strict": s["strict"],
        "strict_percent": round(100 * s["strict"] / s["total"], 2) if s["total"] else 0,
        "flexible": s["flex"],
        "flexible_percent": round(100 * s["flex"] / s["total"], 2) if s["total"] else 0,
        "empty": s["empty"],
        "empty_percent": round(100 * s["empty"] / s["total"], 2) if s["total"] else 0,
        "claude_equivalent": s["claude_equivalent"],
        "claude_equivalent_percent": round(100 * s["claude_equivalent"] / s["total"], 2) if s["total"] else 0,
        "inference_time_avg": round(s["inference_time"] / s["total"], 2) if s["total"] else 0,
    }
    for model, s in stats.items()
}

try:
    if not os.path.exists(STATS_DIR):
        os.makedirs(STATS_DIR)
    if not os.path.exists(BATCH_DIR):
        os.makedirs(BATCH_DIR)
    STATS_FILE = os.path.join(STATS_DIR, "inference_stats.json")
    BATCH_FILE = os.path.join(BATCH_DIR, "claude_batch.json")
    with open(STATS_FILE, "w", encoding="utf-8") as f:
        json.dump(json_data, f, indent=2, ensure_ascii=False)
    with open(BATCH_FILE, "w", encoding="utf-8") as f:
        json.dump(claude_batch_requests, f, ensure_ascii=False)
    print(f"✓ Stats written to: {STATS_FILE}")
    print(f"✓ Batch written to: {BATCH_FILE}")
except Exception as e:
    print(f"ERROR: Failed to write stats file: {e}")
    sys.exit(1)
